using UnityEngine;using UnityEditor;
public static class CounterBloodFinish {public static string Main(){AssetDatabase.Refresh();var mat=AssetDatabase.LoadAssetAtPath<Material>("Assets/Mock/Effects/JustAvoidCounterBlood.mat");mat.SetFloat("_BloodGain",.4f);mat.SetColor("_Tint",new Color(.8f,.35f,1f,1f));mat.SetColor("_VeinColor",new Color(.65f,.012f,.08f,1f));EditorUtility.SetDirty(mat);foreach(bool second in new[]{false,true}){string path="Assets/Mock/Effects/JustAvoidCounter"+(second?"Finisher":"FirstCut")+"CFX.prefab";var go=PrefabUtility.LoadPrefabContents(path);try{foreach(var ps in go.GetComponentsInChildren<ParticleSystem>(true))if(ps.name.Contains("Crimson")){var m=ps.main;m.startSize=new ParticleSystem.MinMaxCurve(second?.085f:.065f,second?.12f:.09f);var emission=ps.emission;var burst=emission.GetBurst(0);burst.count=new ParticleSystem.MinMaxCurve(second?9:6);emission.SetBurst(0,burst);ps.GetComponent<ParticleSystemRenderer>().lengthScale=second?8f:7f;}PrefabUtility.SaveAsPrefabAsset(go,path);}finally{PrefabUtility.UnloadPrefabContents(go);}}AssetDatabase.SaveAssets();return "Dedicated blood adjusted to darker crimson with fewer, thinner, longer threads. Depth test retained.";}}
